// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;


import "./Token.sol";

contract Staking {

    Token public profi;

    mapping(address => uint) public stakes;
    mapping(address => uint) public lastRewardTime;

    uint public totalStaked;
    uint PRECISION = 1e18;

    uint constant public decimals = 10 ** 12;
    uint constant REWARD_PER_SECOND = 13 * decimals;

    constructor(Token professionalCoin) {
        profi = professionalCoin;
    }

    // положить на стэйк
    function stake(uint _amount) public {

        uint amount = _amount * 10 ** profi.decimals();

        require(_amount > 0, "amount is zero");
        require(
            profi.balanceOf(msg.sender) >= amount,
            unicode"Недастаточно LP(profi) токенов на балансе"
        );

        if (stakes[msg.sender] > 0) {
            uint reward = calculateReward();

            if (reward > 0) {
                lastRewardTime[msg.sender] = block.timestamp;
                profi.mint(msg.sender, reward);
            }
        } else {
            lastRewardTime[msg.sender] = block.timestamp;
        }

        stakes[msg.sender] += amount;
        totalStaked += amount;               

        profi.transferFrom(msg.sender, address(this), amount);

    }

    // формула для подсчета
    function calculateReward() public view returns(uint) {

        // для того чтобы не писать каждый раз stakes[msg.sender]
        uint stakedAmount = stakes[msg.sender];

        // проверка на то не является ли его стэйкинг пустым
        if (stakedAmount == 0 || totalStaked == 0) {
            return 0;
        }

        // всё прошедшее время с последнего момента
        uint timeElapsed = block.timestamp - lastRewardTime[msg.sender];

        // проверка на то не является ли его стэйкинг пустым
        if (timeElapsed == 0) {
            return 0;
        }

        // countLP / allLP + 1
        uint stakeMultiplier = PRECISION + (stakedAmount * PRECISION) / totalStaked;

        // ((timeElapsed / 30 days) * 0.05) + 1
        uint timeMultiplier = PRECISION + ((timeElapsed * 5 * PRECISION) / (100 * 30 days));

        // окончательня награда
        uint reward = (
            stakedAmount *
            timeElapsed *
            REWARD_PER_SECOND *
            stakeMultiplier *
            timeMultiplier
        ) / (PRECISION * PRECISION * decimals);

        return reward;
    }

    // забрать со стэйка
    function claimReward() public {
        uint reward = calculateReward();
        require(reward > 0, "No reward available");

        lastRewardTime[msg.sender] = block.timestamp;

        profi.mint(msg.sender, reward);
    }
}

contracts/Token.sol.content:
// contracts/GLDToken.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract Token is ERC20 {

    uint8 constant _decimals = 12;
    uint price;
    uint initialSupply;

    constructor(string memory _name, string memory _symbol, uint _initialSupply, uint _price) ERC20(_name, _symbol) {
        _mint(msg.sender, _initialSupply * 10 ** _decimals);
        price = _price;
        initialSupply = _initialSupply;
    }


    function decimals() public pure override returns (uint8) {
        return _decimals;
    }

    function getPrice() public view returns (uint) {
        return price;
    }

    function mint(address to, uint amount) public {
        _mint(to, amount);
    }

    function getPriceInBuyToken(uint _amount) public view returns(uint) {
        return _amount * getPrice();
    }

    // function buyToken()
    function buyToken(uint _amount) public payable {
        // посчитать количество того, сколько пользователь должен заплатить за токен
        uint amount = _amount * 10 ** decimals();
        uint price = getPriceInBuyToken(_amount);

        // проверить, есть ли такое количество токенов у пользователя
        require(msg.value >= price, unicode"У вас не достаточно ETH для покупки данного количества токенов");

        if (msg.value > price) {
            payable(msg.sender).transfer(msg.value - price); // переводим остаток обратно, при его наличии
        }

        _mint(msg.sender, amount); // минтим новые токены пользователю
    }

}

